const listAdvisoryIdentifiers = `-- name: ListAdvisoryIdentifiers :many
SELECT upper(a.canonical_id)::text AS identifier FROM advisories a WHERE a.id = $1
UNION
SELECT upper(x.alias)::text FROM advisory_aliases x WHERE x.advisory_id = $1
`

// Every name of an advisory: its canonical id and its aliases, upper-cased.
func (q *Queries) ListAdvisoryIdentifiers(ctx context.Context, advisoryID uuid.UUID) ([]string, error) {
	rows, err := q.db.QueryContext(ctx, listAdvisoryIdentifiers, advisoryID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var identifier string
		if err := rows.Scan(&identifier); err != nil {
			return nil, err
		}
		items = append(items, identifier)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

