const moveIncidentChildren = `-- name: MoveIncidentChildren :exec
WITH moved_events AS (
    UPDATE incident_events SET incident_id = $1 WHERE incident_id = $2
), moved_deliveries AS (
    UPDATE incident_deliveries SET incident_id = $1 WHERE incident_id = $2
)
UPDATE incident_actions a SET incident_id = $1
WHERE a.incident_id = $2
  AND a.state <> 'pending'
  AND NOT EXISTS (
      SELECT 1 FROM incident_actions s
      WHERE s.incident_id = $1 AND s.kind = a.kind AND s.subject_type = a.subject_type AND s.subject_id = a.subject_id
  )
`

type MoveIncidentChildrenParams struct {
	Survivor uuid.UUID `json:"survivor"`
	Merged   uuid.UUID `json:"merged"`
}

// Merging (ADR-053 §3): the survivor absorbs the other incident's history.
func (q *Queries) MoveIncidentChildren(ctx context.Context, arg MoveIncidentChildrenParams) error {
	_, err := q.db.ExecContext(ctx, moveIncidentChildren, arg.Survivor, arg.Merged)
	return err
}

